 color: colors.onSurface,
 },
 welcomeSubtitle: {
 fontFamily: "JetBrainsMono",
 fontSize: 16,
 lineHeight: 24,
 color: colors.onSurfaceVariant,
 marginTop: 16,
 },
 tagItem: {
 alignItems: "center",
 paddingHorizontal: 16,
 paddingVertical: 8,
 borderRadius: 9999,
 backgroundColor: colors.surfaceContainer,
 },
 tagDot: {
 width: 12,
 height: 12,
 borderRadius: 9999,
 backgroundColor: derivedColors.primary,
 marginRight: 8,
 },
 tagLabel: {
 fontFamily: "JetBrainsMono",
 fontSize: 12,
 textTransform: "uppercase",
 letterSpacing: 0.5,
 color: colors.onSurfaceVariant,
 },
 codeBlock: {
 backgroundColor: colors.surfaceContainerLowest,
 padding: 16,
 borderRadius: 8,
 },
 codeBlockHeader: {
 justifyContent: "space-between",
 alignItems: "center",
 marginBottom: 8,
 paddingBottom: 8,
 },
 codeBlockLabel: {
 color: derivedColors.primary,
 fontWeight: "700",
 fontSize: 11,
 textTransform: "uppercase",
 },
 codeTextPink: {
 fontFamily: "JetBrainsMono",
 fontSize: 12,
 color: derivedColors.primary,
 },
 codeTextWhite: {
 fontFamily: "JetBrainsMono",
 fontSize: 12,
 color: colors.onSurface,
 paddingLeft: 16,
 },
 codeTextPink2: {
 fontFamily: "JetBrainsMono",
 fontSize: 12,
 color: derivedColors.primary,
 paddingLeft: 16,
 },
 slideTitle: {
 fontFamily: "JetBrainsMono",
 fontSize: 24,
 fontWeight: "700",
 color: colors.onSurface,
 },
 slideSubtitle: {
 fontFamily: "JetBrainsMono",
 fontSize: 16,
 color: colors.onSurfaceVariant,
 marginTop: 8,
 },
 optionCard: {
 padding: 16,
 borderRadius: 20,
 },
 optionTitle: {
 fontFamily: "JetBrainsMono",
 fontSize: 20,
 fontWeight: "700",
 },
 optionDesc: {
 fontFamily: "JetBrainsMono",
 fontSize: 16,
 marginTop: 4,
 },
