 width: 32,
 height: 32,
 borderRadius: 9999,
 backgroundColor: derivedColors.primary,
 alignItems: "center",
 justifyContent: "center",
 },
 moduleNumberText: {
 fontFamily: "JetBrainsMono",
 fontWeight: "700",
 color: colors.onPrimary,
 },
 moduleName: {
 fontFamily: "JetBrainsMono",
 fontSize: 20,
 fontWeight: "700",
 color: colors.onSurface,
 },
 moduleDesc: {
 fontFamily: "JetBrainsMono",
 fontSize: 16,
 color: colors.onSurfaceVariant,
 marginTop: 2,
 },
 readyCta: {
 fontFamily: "JetBrainsMono",
 fontSize: 20,
 fontWeight: "700",
